public class ArgAverageTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String run(String... args) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ArgAverage.main(args);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("no arguments prints usage",
                "usage: java ArgAverage <number> [number ...]\n", run());
        check("three whole numbers", "count: 3\naverage: 4.00\n", run("3", "4", "5"));
        check("decimals and negatives", "count: 2\naverage: 0.50\n", run("2.5", "-1.5"));
        check("single argument", "count: 1\naverage: 7.00\n", run("7"));
        check("repeating average is rounded", "count: 3\naverage: 3.33\n", run("2", "4", "4"));
        check("all negative", "count: 2\naverage: -5.00\n", run("-4", "-6"));
        check("usage line is the only line when empty", 1, run().split("\n", -1).length - 1);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

