public class ArgAverage {

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("usage: java ArgAverage <number> [number ...]");
            return;
        }
        double total = 0.0;
        for (String arg : args) {
            total = total + Double.parseDouble(arg);
        }
        double average = total / args.length;
        System.out.println("count: " + args.length);
        System.out.printf(java.util.Locale.US, "average: %.2f%n", average);
    }
}
